#!/bin/bash
# Domain C verification: tiny magnitudes & scientific notation
REF=/workspace/dataset/test17_executable
RUST=/output/test17

total=0
mism=0
declare -a report

check() {
    total=$((total+1))
    a=$("$REF" "$@" 2>/dev/null); ra=$?
    b=$("$RUST" "$@" 2>/dev/null); rb=$?
    if [ "$a" != "$b" ]; then
        mism=$((mism+1))
        if [ ${#report[@]} -lt 10 ]; then
            report+=("ARGS: $*"$'\n'"  REF  (exit $ra): [$a]"$'\n'"  RUST (exit $rb): [$b]")
        fi
    elif [ "$ra" != "$rb" ]; then
        # stdout matches but exit codes differ (expected for subnormal/underflow)
        if [ ${#report[@]} -lt 10 ]; then
            report+=("EXIT-CODE-ONLY DIFF ARGS: $*"$'\n'"  REF exit $ra, RUST exit $rb (stdout identical, empty)")
        fi
    fi
}

# 1) Random log-uniform args in [1e-38, 1e-2], both signs, %.8e and %.6e
for i in $(seq 1 400); do
    mapfile -t args < <(awk -v s=$((i*7919+13)) 'BEGIN{
        srand(s);
        efmt = (rand() < 0.5) ? "%.8e" : "%.6e";
        for (k=0;k<3;k++){
            e = -38 + rand()*36;      # exponent in [-38,-2]
            m = 1 + rand()*9;         # mantissa in [1,10)
            v = m * (10 ^ e);
            if (rand() < 0.5) v = -v;
            printf efmt "\n", v;
        }
    }')
    check "${args[@]}"
done

# 2) Explicit normals near FLT_MIN
near_min=(1.17549435e-38 1.1754944e-38 1.1754945e-38 1.1754943e-38 1.17549436e-38 -1.17549435e-38 1.175494e-38 1.18e-38 2e-38 5e-38 1.2e-38 1.1754944e-38)
for i in $(seq 1 50); do
    read -r a1 a2 a3 <<<"$(awk -v s=$((i*104729+7)) 'BEGIN{
        srand(s);
        vals[0]="1.17549435e-38"; vals[1]="1.1754944e-38"; vals[2]="1.1754943e-38";
        vals[3]="-1.17549435e-38"; vals[4]="1.17549436e-38"; vals[5]="2e-38"; vals[6]="1.2e-38";
        for (k=0;k<3;k++){ v=vals[int(rand()*7)]; printf "%s ", v; }
        printf "\n";
    }')"
    check "$a1" "$a2" "$a3"
done

# 3) Subnormal literals (stdout must be empty; exit codes may differ)
sub=(1e-39 1e-45 5e-40 1e-40 1.4e-45 -1e-39 -1e-45 1e-42 7e-44 1e-44)
for i in $(seq 1 30); do
    read -r a1 a2 a3 <<<"$(awk -v s=$((i*31337+3)) 'BEGIN{
        srand(s);
        vals[0]="1e-39"; vals[1]="1e-45"; vals[2]="5e-40"; vals[3]="1e-40";
        vals[4]="1.4e-45"; vals[5]="-1e-39"; vals[6]="-1e-45"; vals[7]="1e-42";
        for (k=0;k<3;k++) printf "%s ", vals[int(rand()*8)];
        printf "\n";
    }')"
    check "$a1" "$a2" "$a3"
done

# 4) Underflow literals 1e-46 (flush to zero / abort)
und=(1e-46 -1e-46 1e-46 1e-46 1e-47)
for i in $(seq 1 20); do
    read -r a1 a2 a3 <<<"$(awk -v s=$((i*99991+11)) 'BEGIN{
        srand(s);
        vals[0]="1e-46"; vals[1]="-1e-46"; vals[2]="1e-47"; vals[3]="0e0";
        for (k=0;k<3;k++) printf "%s ", vals[int(rand()*4)];
        printf "\n";
    }')"
    check "$a1" "$a2" "$a3"
done

echo "=== TOTAL: $total  MISMATCHES: $mism ==="
for r in "${report[@]}"; do
    echo "---"
    echo "$r"
done

